  "privFooter": "Privatësia dhe ruajtja",
  "privTitle": "Privatësia dhe ruajtja në shfletues",
  "privClose": "Mbyll njoftimin e privatësisë",
  "privWho": "Kush është përgjegjës?",
  "privWhat": "Çfarë përdorim dhe pse",
  "privStorage": "Ruajtja në shfletues",
  "privOther": "Veçori të tjera ekzistuese",
  "privProviders": "Ofruesit e shërbimeve dhe transferimet ndërkombëtare",
  "privRetention": "Ruajtja dhe fshirja",
  "privRights": "Të drejtat e tua",
  "noticeReopen": "Njoftim për ruajtjen",
  "noticeLabel": "Njoftim për ruajtjen në shfletues",
  "noticeText": "Cook përdor ruajtjen e shfletuesit për veçoritë e gatimit dhe të hyrjes që përdor. Nuk shtohet ruajtje për reklama ose analitikë.",
  "noticeClose": "Mbyll njoftimin për ruajtjen",
  "privDraftLabel": "Draft — përditësuar më 28 tetor 2026.",
  "privDraft": "Veçoritë e llogarisë po testohen aktualisht. Të dhënat e operatorit dhe të shërbimeve më poshtë duhet të plotësohen para nisjes publike.",
  "privWho1": "Cook operohet nga [emri ligjor dhe adresa postare e operatorit]. Për pyetje dhe kërkesa mbi privatësinë, shkruaj te [adresa e email-it për privatësinë]. Këto të dhëna duhet të plotësohen para se të hapet regjistrimi.",
  "privWhat1": "Kur krijon një llogari, përdorim email-in tënd, një identifikues llogarie, të dhënat e vërtetimit me fjalëkalim dhe statusin e verifikimit për të ofruar dhe mbrojtur llogarinë tënde. Fjalëkalimet trajtohen nga ofruesi i vërtetimit si hash-e të sigurta; Cook nuk ruan fjalëkalime të lexueshme. Ruajmë rregullimin e kuzhinës, gjuhën e zgjedhur, temën dhe njësitë matëse për të rikthyer cilësimet e tua në të gjitha pajisjet. Për llogari nevojiten email dhe fjalëkalim; recetat mund t’i shfletosh edhe pa llogari.",
  "privWhat2": "Përpunimi i llogarisë dhe i cilësimeve është i nevojshëm për të ofruar shërbimin e llogarisë që kërkon (neni 6(1)(b) i GDPR). Të dhëna të kufizuara sigurie dhe parandalimi të abuzimit mund të përpunohen në bazë të interesave legjitime (neni 6(1)(f)), në masën e nevojshme dhe pas balancimit. Email-et e verifikimit dhe të rivendosjes së fjalëkalimit janë mesazhe shërbimi, jo marketing. Veçoria e llogarisë nuk shton reklama ose analitikë.",
  "privStorage1": "Cook përdor sessionStorage për të mbartur kuzhinën, përparimin në gatim dhe zgjedhjet e tua mes faqeve në të njëjtën skedë. Kur ke hyrë, ruan edhe sesionin tënd të hyrjes. Shfletuesi zakonisht i fshin këto kur mbaron sesioni i skedës, por rikthimi i sesionit nga shfletuesi mund t’i ruajë. Dalja fshin të dhënat e skedës së Cook. Mbyllja e njoftimit për ruajtjen mbahet mend vetëm në atë skedë. Skriptet e vetë Cook nuk vendosin cookies. Ofruesit e tu të strehimit ose të shërbimeve mund të kenë përpunime të veta sigurie që duhet të dokumentohen para nisjes.",
  "privStorage2": "OK dhe butoni i mbylljes së njoftimit për ruajtjen vetëm e mbyllin njoftimin. Ata nuk autorizojnë analitikë, reklama ose gjurmim tjetër opsional. Çdo ruajtje jo thelbësore në të ardhmen do të kërkojë një zgjedhje të veçantë para se të nisë, me refuzim dhe tërheqje po aq të lehta.",
  "privOther1": "Veçoria aktuale zanore e listës së recetave i kërkon country.is një vend të përafërt bazuar në adresën tënde IP, për të zgjedhur gjuhën e njohjes së zërit. Nëse përdor njohjen me mikrofon, shfletuesi mund t’ia dërgojë audion ofruesit të vet të njohjes së zërit. Përbërësit mund t’i shkruash edhe me tastierë. Këta ofrues, politikat e tyre dhe baza ligjore e këtyre veçorive duhet të shqyrtohen para nisjes publike.",
  "privProviders1": "Ofruesi i planifikuar i llogarive: Supabase (PostgreSQL dhe vërtetim i menaxhuar), me një rajon të zgjedhur databaze në BE. Ofruesi i email-it: [ofruesi]. Strehimi i faqes: [ofruesi]. Operatori duhet të konfirmojë ofruesit realë, marrëveshjet e përpunimit, nënpërpunuesit, vendndodhjet e regjistrave dhe çdo transferim jashtë ZEE. Një rajon databaze në BE nuk përjashton vetvetiu transferimet ndërkombëtare. Kur është e nevojshme, trego vendimin e përshtatshmërisë ose garancitë kontraktuale të zbatueshme dhe si mund të merret një kopje.",
  "privRetention1": "Cilësimet e llogarisë ruhen për sa kohë llogaria jote është aktive. Mund të kërkosh fshirjen përmes kontaktit të privatësisë më lart. Para nisjes, operatori duhet të përcaktojë procesin e përgjigjes ndaj kërkesave për fshirje, skadimin e llogarive të paverifikuara dhe afatet e ruajtjes së regjistrave të sigurisë dhe të kopjeve rezervë. Të dhënat e fshira mund të mbeten në kopje rezervë me qasje të kufizuar deri në fund të afatit të dokumentuar të ruajtjes.",
  "privRights1": "Në varësi të kushteve të zbatueshme, mund të kërkosh qasje, korrigjim, fshirje, kufizim ose transferueshmëri, ose të kundërshtosh përpunimin e bazuar në interes legjitim. Kontakto operatorin më lart; kërkesave zakonisht u përgjigjemi brenda një muaji dhe çdo zgjatje e ligjshme shpjegohet. Mund të paraqesësh ankesë te autoriteti mbikëqyrës, përfshirë NAIH-in e Hungarisë në naih.hu. Cook nuk i përdor cilësimet e llogarisë për vendime të automatizuara me efekte ligjore ose efekte të ngjashme të rëndësishme.",
