  "privCommunity": "Nëse zgjedh një emër përdoruesi, ai shfaqet pranë komenteve të tua publike. Komentet dhe data e tyre janë të dukshme për të gjithë, bashkë me yjet që i dhe recetës; mesataret shfaqen pa emra. Historiku i recetave, shënimet personale dhe lista e blerjeve janë private. Fshirja e llogarisë i heq të gjitha.",
  "privRatings": "Kur je i identifikuar, vlerësimet e tua me 1–5 yje ruhen me identifikuesin e llogarisë dhe të recetës. Një vlerësim i ri zëvendëson të vjetrin. Vlerësimet pa hyrje nuk ruhen dhe nuk ngarkohen më vonë.",
